def _final_payload(
    client: OpenAIClient, prompt: str, args: argparse.Namespace, kwargs: Mapping[str, Any]
) -> Mapping[str, Any]:
    """Return the raw response JSON, streaming or not, for ``--json``."""
    if not args.stream:
        return client.responses.create(prompt, **kwargs).raw
    final: Mapping[str, Any] = {}
    for event in client.responses.stream(prompt, **kwargs):
        if event.type in ("response.completed", "response.incomplete") and isinstance(event.data.get("response"), Mapping):
            final = event.data["response"]
        elif event.type == "response.completed" and event.response is not None:
            final = event.response.raw
    return final


